export const GLYPH_TABLE: { fontId: string; upem: number; glyphs: Map<string, GlyphRow> } = (() => {
  const parsed = JSON.parse(TABLE_JSON) as { fontId: string; upem: number; glyphs: GlyphRow[] };
  return { fontId: parsed.fontId, upem: parsed.upem, glyphs: new Map(parsed.glyphs.map((g) => [g.char, g])) };
})();

